  if (headEnd > MAX_HEAD_BYTES) return { error: true };

  const [requestLine, ...headerLines] = receivedBytes.toString('latin1', 0, headEnd).split('\\r\\n');
  if (requestLine.length > MAX_REQUEST_LINE_BYTES) return { error: true };
  const parsedLine = parseRequestLine(requestLine);
  if (!parsedLine) return { error: true };

