  for (const line of headerLines) {
    const match = HEADER_LINE_PATTERN.exec(line);
    if (!match) return { error: true };
    const name = match[1].toLowerCase();
    if (name in headers) {
      if (name === 'content-length' && headers[name] !== match[2]) return { error: true };
